	/**  Validated ISBN-10 (digits only). */
	isbn10: string | null,
	/**  Validated ISBN-13 (digits only). */
	isbn13: string | null,
	/**  Edition statement (`الطبعة الثالثة`, `3rd ed.`…). */
	edition: string | null,
	/**  Year of this edition's publication. */
