/**
 *  A quote with the two book facts the global quotes screen renders.
 * 
 *  The join is presentation-facing, like [`crate::repo::book::BookDetail`]: [`Quote`] stays
 *  pure and the screen never joins per row.
 */
export type QuoteWithBook = {
	/**  The quote itself. */
	quote: Quote,
	/**  The book's title. */
	book_title: string,
	/**  First author credited on the book, if any (display order). */
	book_author: string | null,
};

/**
 *  Current reading status of a book (the brief: to-read / reading / finished / paused /
 *  abandoned — Hard Cover's "did not finish" maps to `Abandoned`).
 */
export type ReadingStatus = "to_read" | "reading" | "finished" | "paused" | "abandoned";

/**
 *  A book series (السلسلة).
 * 
 *  A book belongs to at most one series in v1 — a deliberate simplification documented in
 *  `docs/03-data-model.md`; multi-series membership would complicate the add form for a case
 *  that is rare in practice.
 */
export type Series = {
	/**  UUID v7. */
	id: string,
	/**  Name as written. */
	name: string,
	/**  Normalized mirror. */
	name_norm: string,
	/**  Description. */
	description: string | null,
	/**  Creation timestamp, epoch ms UTC. */
	created_at: number,
	/**  Last update timestamp, epoch ms UTC. */
	updated_at: number,
};

/**  Input for creating or updating a [`Series`]. */
export type SeriesInput = {
	/**  Name (required). */
	name: string,
	/**  Description. */
	description: string | null,
};

/**  How an attachment is stored. */
export type StorageMode = 
/**  Copied into the library, content-addressed by SHA-256. */
"copy" | 
/**  Left where the user put it; only the path and hash are recorded. */
"reference";

/**
 *  A free-form label (الوسم) the user attaches to books.
 * 
 *  Tags are flat and unordered by design: a label that needs a hierarchy wants to be a
 *  category instead.
 */
export type Tag = {
	/**  UUID v7. */
	id: string,
	/**  Name as written. */
	name: string,
	/**  Normalized mirror; uniqueness comes from `ux_tags_name_norm`. */
	name_norm: string,
	/**  Optional colour, `#RRGGBB`. */
	color: string | null,
	/**  Creation timestamp, epoch ms UTC. */
	created_at: number,
};

/**  Input for creating or renaming a [`Tag`]. */
export type TagInput = {
	/**  Name (required). */
	name: string,
	/**  Optional colour. */
	color: string | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

